package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	planReusePenalty float64
	lastFailedShard  lnwire.MilliSatoshi
	attempts         int
	attemptLimit     int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*4 + 12
	if r.attemptLimit < 28 {
		r.attemptLimit = 28
	}
	if r.attemptLimit > 80 {
		r.attemptLimit = 80
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probabilityWithTotal(edge *candidateEdge,
	htlcAmt, total lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(htlcAmt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		retryCeiling := failure.upper * 3 / 4
		if retryCeiling == 0 {
			retryCeiling = 1
		}
		if total > retryCeiling {
			return 0
		}

		retryScale = 0.60 / math.Sqrt(float64(failure.count))
		if retryScale < 0.15 {
			retryScale = 0.15
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.012 {
			p = 0.012
		}
		return p * retryScale
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		evidence := 0.985 - 0.97*pos
		p = 0.18*p + 0.82*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.50 {
			scale := 1 - 0.92*(ratio-0.50)/0.50
			if scale < 0.08 {
				scale = 0.08
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.48 * math.Exp(-distance/0.18)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.11 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.68*p + 0.32*q
	}

	p *= retryScale
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	return r.probabilityWithTotal(
		edge, amt, amt+r.reserved[edge.key],
	)
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 420_000.0
		hopPenalty = 220.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 18_000
			edgeScore += float64(r.suspect[edge.key]) * 230_000

			if r.reserved[edge.key] > 0 {
				edgeScore += r.planReusePenalty
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

type candidatePlanEdgeLoad struct {
	total lnwire.MilliSatoshi
	max   lnwire.MilliSatoshi
	uses  uint32
}

func (r *candidateRouter) scorePlan(plan []*route.Route,
	baseReservations map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	loads := make(map[candidateEdgeKey]candidatePlanEdgeLoad)
	var fees lnwire.MilliSatoshi

	for _, rt := range plan {
		finalAmt := candidateFinalAmount(rt)
		fees += rt.TotalAmount - finalAmt

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				return math.Inf(-1)
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				return math.Inf(-1)
			}

			load := loads[key]
			load.total += amt
			if amt > load.max {
				load.max = amt
			}
			load.uses++
			loads[key] = load
		}
	}

	score := -float64(fees)/4_000_000 - 0.025*float64(len(plan))

	for key, load := range loads {
		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		total := baseReservations[key] + load.total
		p := r.probabilityWithTotal(edge, load.max, total)
		if p <= 0 {
			return math.Inf(-1)
		}
		score += math.Log(p)

		if load.uses > 1 && edge.key.from != r.source {
			score -= 0.22 * float64(load.uses-1)
		}
	}

	return score
}

func (r *candidateRouter) planOnce(total lnwire.MilliSatoshi,
	parts uint32, sizeBias, reusePenalty float64) (
	[]*route.Route, bool) {

	savedReservations := candidateCopyReservations(r.reserved)
	savedPenalty := r.planReusePenalty
	defer func() {
		r.reserved = savedReservations
		r.planReusePenalty = savedPenalty
	}()

	r.planReusePenalty = reusePenalty
	remaining := total
	slots := parts
	var plan []*route.Route

	for remaining > 0 && slots > 0 {
		if slots == 1 {
			rt, _, err := r.findRoute(remaining)
			if err != nil {
				return nil, false
			}
			plan = append(plan, rt)
			r.reserveRoute(rt)
			remaining = 0
			break
		}

		base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		var sizes []lnwire.MilliSatoshi
		seen := make(map[lnwire.MilliSatoshi]bool)

		candidateAddAmount(&sizes, seen, base/2, remaining)
		candidateAddAmount(&sizes, seen, base*3/4, remaining)
		candidateAddAmount(&sizes, seen, base*7/8, remaining)
		candidateAddAmount(&sizes, seen, base, remaining)
		candidateAddAmount(&sizes, seen, base*5/4, remaining)
		candidateAddAmount(&sizes, seen, base*3/2, remaining)
		candidateAddAmount(&sizes, seen, base*2, remaining)
		candidateAddAmount(&sizes, seen, base*3, remaining)
		candidateAddAmount(&sizes, seen, remaining, remaining)

		if r.lastFailedShard > 0 {
			candidateAddAmount(
				&sizes, seen, r.lastFailedShard/2, remaining,
			)
			candidateAddAmount(
				&sizes, seen, r.lastFailedShard*5/8, remaining,
			)
			candidateAddAmount(
				&sizes, seen, r.lastFailedShard*3/4, remaining,
			)
		}

		var bestRoute *route.Route
		bestSize := lnwire.MilliSatoshi(0)
		bestUtility := math.Inf(-1)

		for _, size := range sizes {
			rt, logProb, err := r.findRoute(size)
			if err != nil {
				continue
			}

			fees := rt.TotalAmount - size
			sizeReward := math.Log(
				float64(size) / float64(base),
			)
			utility := logProb + sizeBias*sizeReward -
				float64(fees)/4_000_000

			if bestRoute == nil || utility > bestUtility {
				bestRoute = rt
				bestSize = size
				bestUtility = utility
			}
		}

		if bestRoute == nil {
			return nil, false
		}

		plan = append(plan, bestRoute)
		r.reserveRoute(bestRoute)
		remaining -= bestSize
		slots--
	}

	if remaining != 0 || len(plan) == 0 {
		return nil, false
	}
	return plan, true
}

func (r *candidateRouter) fallbackShard(total lnwire.MilliSatoshi,
	parts uint32) (*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total)
		return rt, err
	}

	base := (total + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, total, total)
	candidateAddAmount(&sizes, seen, total*3/4, total)
	candidateAddAmount(&sizes, seen, total/2, total)
	candidateAddAmount(&sizes, seen, base*3/2, total)
	candidateAddAmount(&sizes, seen, base, total)
	candidateAddAmount(&sizes, seen, base*3/4, total)
	candidateAddAmount(&sizes, seen, base/2, total)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*3/4, total,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8, total,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2, total,
		)
	}

	var best *route.Route
	bestUtility := math.Inf(-1)

	for _, size := range sizes {
		rt, logProb, err := r.findRoute(size)
		if err != nil {
			continue
		}

		fees := rt.TotalAmount - size
		progress := math.Log(float64(size) / float64(base))
		utility := logProb + 0.62*progress -
			float64(fees)/4_000_000

		if best == nil || utility > bestUtility {
			best = rt
			bestUtility = utility
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}
	return best, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32, inFlight uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	if inFlight == 0 && r.lastFailedShard == 0 {
		full, logProb, err := r.findRoute(total)
		if err == nil && logProb >= math.Log(0.24) {
			return []*route.Route{full}, nil
		}
	}

	type planConfig struct {
		sizeBias    float64
		reusePenalty float64
	}

	configs := []planConfig{
		{sizeBias: 0.18, reusePenalty: 180_000},
		{sizeBias: 0.40, reusePenalty: 520_000},
		{sizeBias: 0.68, reusePenalty: 1_050_000},
		{sizeBias: 0.95, reusePenalty: 1_700_000},
	}

	baseReservations := candidateCopyReservations(r.reserved)
	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	for _, config := range configs {
		plan, ok := r.planOnce(
			total, parts, config.sizeBias, config.reusePenalty,
		)
		if !ok {
			continue
		}

		score := r.scorePlan(plan, baseReservations)
		if bestPlan == nil || score > bestScore {
			bestPlan = plan
			bestScore = score
		}
	}

	if bestPlan != nil {
		return bestPlan, nil
	}

	rt, err := r.fallbackShard(total, parts)
	if err != nil {
		return nil, err
	}
	return []*route.Route{rt}, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft, inFlightHtlcs)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(candidateVertexHash(e.key.to) +
		0x9e3779b97f4a7c15)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(uint64(e.baseFeeMsat) +
		uint64(e.feeRatePPM)<<17)
	x ^= candidateMix64(uint64(e.timeLockDelta) +
		uint64(e.minHTLC)<<16)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*3 + 8
	if r.attemptLimit < 24 {
		r.attemptLimit = 24
	}
	if r.attemptLimit > 64 {
		r.attemptLimit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	reserved := r.reserved[edge.key]
	total := amt + reserved

	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok {
		if failure.count >= 2 {
			return 0
		}
		if failure.upper > 0 {
			if total >= failure.upper {
				return 0
			}

			retryCeiling := failure.upper * 2 / 3
			if retryCeiling == 0 {
				retryCeiling = 1
			}
			if total > retryCeiling {
				return 0
			}
			retryScale = 0.35
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.012 {
			p = 0.012
		}
		return p * retryScale
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		evidence := 0.985 - 0.97*pos
		p = 0.2*p + 0.8*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.55 {
			scale := 1 - 0.92*(ratio-0.55)/0.45
			if scale < 0.08 {
				scale = 0.08
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.45 * math.Exp(-distance/0.18)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.12 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.7*p + 0.3*q
	}

	p *= retryScale
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 420_000.0
		hopPenalty = 220.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 22_000
			edgeScore += float64(r.suspect[edge.key]) * 260_000

			if r.reserved[edge.key] > 0 {
				edgeScore += 260_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) planOnce(total lnwire.MilliSatoshi,
	parts uint32, sizeBias float64) ([]*route.Route, float64, bool) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	remaining := total
	slots := parts
	var plan []*route.Route
	jointScore := 0.0

	for remaining > 0 && slots > 0 {
		if slots == 1 {
			rt, logProb, err := r.findRoute(remaining)
			if err != nil {
				return nil, 0, false
			}

			fees := rt.TotalAmount - remaining
			jointScore += logProb -
				float64(fees)/4_000_000 - 0.025
			plan = append(plan, rt)
			r.reserveRoute(rt)
			remaining = 0
			break
		}

		base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		var sizes []lnwire.MilliSatoshi
		seen := make(map[lnwire.MilliSatoshi]bool)

		candidateAddAmount(&sizes, seen, base, remaining)
		candidateAddAmount(&sizes, seen, base*5/4, remaining)
		candidateAddAmount(&sizes, seen, base*3/2, remaining)
		candidateAddAmount(&sizes, seen, base*2, remaining)
		candidateAddAmount(&sizes, seen, base*3, remaining)
		candidateAddAmount(&sizes, seen, remaining, remaining)

		if r.lastFailedShard > 0 {
			candidateAddAmount(
				&sizes, seen, r.lastFailedShard*5/8,
				remaining,
			)
		}

		var bestRoute *route.Route
		bestSize := lnwire.MilliSatoshi(0)
		bestLogProb := 0.0
		bestUtility := math.Inf(-1)

		for _, size := range sizes {
			rt, logProb, err := r.findRoute(size)
			if err != nil {
				continue
			}

			fees := rt.TotalAmount - size
			sizeReward := math.Log(
				float64(size) / float64(base),
			)
			utility := logProb + sizeBias*sizeReward -
				float64(fees)/4_000_000

			if bestRoute == nil || utility > bestUtility {
				bestRoute = rt
				bestSize = size
				bestLogProb = logProb
				bestUtility = utility
			}
		}

		if bestRoute == nil {
			return nil, 0, false
		}

		fees := bestRoute.TotalAmount - bestSize
		jointScore += bestLogProb -
			float64(fees)/4_000_000 - 0.025

		plan = append(plan, bestRoute)
		r.reserveRoute(bestRoute)
		remaining -= bestSize
		slots--
	}

	if remaining != 0 || len(plan) == 0 {
		return nil, 0, false
	}
	return plan, jointScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32, inFlight uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	if inFlight == 0 && r.lastFailedShard == 0 {
		full, logProb, err := r.findRoute(total)
		if err == nil && logProb >= math.Log(0.22) {
			return []*route.Route{full}, nil
		}
	}

	biases := []float64{0.28, 0.48, 0.72}
	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	for _, bias := range biases {
		plan, score, ok := r.planOnce(total, parts, bias)
		if !ok {
			continue
		}
		if bestPlan == nil || score > bestScore {
			bestPlan = plan
			bestScore = score
		}
	}

	if bestPlan == nil {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}
	return bestPlan, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		if candidateFinalAmount(rt) > 0 &&
			candidateFinalAmount(rt) <= amt {

			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft, inFlightHtlcs)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*3 + 10
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 64 {
		r.attemptLimit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999
	}

	p := candidatePrior(total, edge.capacity)
	belief, known := r.beliefs[edge.key]

	if known {
		switch {
		case belief.lowerOK > 0 && total <= belief.lowerOK:
			p = 0.995

		case belief.upperFail > 0 && total >= belief.upperFail:
			if p > 0.015 {
				p = 0.015
			}

		case belief.lowerOK > 0 &&
			belief.upperFail > belief.lowerOK:

			width := float64(
				belief.upperFail - belief.lowerOK,
			)
			pos := float64(total-belief.lowerOK) / width
			if pos < 0 {
				pos = 0
			}
			if pos > 1 {
				pos = 1
			}
			evidence := 0.99 - 0.975*pos
			p = 0.18*p + 0.82*evidence

		case belief.upperFail > 0:
			ratio := float64(total) /
				float64(belief.upperFail)
			if ratio > 0.45 {
				scale := 1 - 0.9*(ratio-0.45)/0.55
				if scale < 0.1 {
					scale = 0.1
				}
				p *= scale
			}

		case belief.lowerOK > 0 && total > belief.lowerOK:
			distance := float64(total-belief.lowerOK) /
				float64(edge.capacity)
			boost := 0.5 * math.Exp(-distance/0.2)
			p += boost * (1 - p)
		}

		if belief.estimate > 0 &&
			!(belief.lowerOK > 0 && total <= belief.lowerOK) {

			scale := 0.1 * float64(edge.capacity)
			if scale < 1 {
				scale = 1
			}
			q := 1 / (1 + math.Exp(
				(float64(total)-float64(belief.estimate)) /
					scale,
			))
			p = 0.72*p + 0.28*q
		}
	}

	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			refresh := 0.006 /
				(1 + 0.5*float64(failure.count))
			if p > refresh {
				p = refresh
			}
		} else {
			ratio := float64(total) /
				float64(failure.upper)
			if ratio > 0.45 {
				scale := 1 - 0.82*(ratio-0.45)/0.55
				if scale < 0.18 {
					scale = 0.18
				}
				p *= scale
			} else {
				p *= 0.8
			}
		}
	}

	if p < 0.001 {
		return 0.001
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	total := amt + r.reserved[edge.key]
	if total < amt {
		return 0
	}

	return r.liquidityProbability(edge, total)
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	index    int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 360_000.0
		hopPenalty = 3_500.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee
			if sending < amtOver {
				continue
			}

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 8_000
			edgeScore += float64(r.suspect[edge.key]) * 150_000

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateReserveInto(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amt
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveInto(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) planningSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, base/2, remaining)
	candidateAddAmount(&sizes, seen, base*3/4, remaining)
	candidateAddAmount(&sizes, seen, base, remaining)
	candidateAddAmount(&sizes, seen, base*5/4, remaining)
	candidateAddAmount(&sizes, seen, base*3/2, remaining)
	candidateAddAmount(&sizes, seen, base*2, remaining)
	candidateAddAmount(&sizes, seen, base*3, remaining)
	candidateAddAmount(&sizes, seen, remaining, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*3/4, remaining,
		)
	}

	sort.Slice(sizes, func(i, j int) bool {
		di := sizes[i] - base
		if di < 0 {
			di = -di
		}
		dj := sizes[j] - base
		if dj < 0 {
			dj = -dj
		}
		return di < dj
	})

	if len(sizes) > 10 {
		sizes = sizes[:10]
	}
	return sizes
}

func (r *candidateRouter) jointPlanScore(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	totalFees lnwire.MilliSatoshi, parts int) float64 {

	score := 0.0
	for key, total := range reservations {
		edge := r.edges[key]
		if edge == nil {
			continue
		}

		p := r.liquidityProbability(edge, total)
		if p <= 0 {
			return math.Inf(-1)
		}
		score += math.Log(p)
	}

	score -= float64(totalFees) / 3_500_000
	score -= 0.035 * float64(parts)
	return score
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	totalFees    lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		parts = 1
	}
	if parts == 1 {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	initial := candidatePlanState{
		remaining:    total,
		reservations: candidateCopyReservations(savedReservations),
	}
	initial.score = r.jointPlanScore(
		initial.reservations, 0, 0,
	)

	states := []candidatePlanState{initial}
	var bestComplete *candidatePlanState

	const beamWidth = 10

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		var nextStates []candidatePlanState

		for _, state := range states {
			if state.remaining == 0 {
				copyState := state
				if bestComplete == nil ||
					copyState.score > bestComplete.score {

					bestComplete = &copyState
				}
				continue
			}

			sizes := r.planningSizes(state.remaining, slots)
			r.reserved = state.reservations

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				rt, _, err := r.findRoute(size)
				if err != nil {
					continue
				}

				reservations := candidateCopyReservations(
					state.reservations,
				)
				candidateReserveInto(reservations, rt)

				fees := rt.TotalAmount - size
				if fees < 0 {
					continue
				}

				next := candidatePlanState{
					remaining: state.remaining - size,
					routes: append(
						append(
							[]*route.Route(nil),
							state.routes...,
						),
						rt,
					),
					reservations: reservations,
					totalFees:    state.totalFees + fees,
				}
				next.score = r.jointPlanScore(
					next.reservations, next.totalFees,
					len(next.routes),
				)
				if math.IsInf(next.score, -1) {
					continue
				}

				delivered := float64(total-next.remaining) /
					float64(total)
				next.rank = next.score + 3.0*delivered

				if next.remaining == 0 {
					copyState := next
					if bestComplete == nil ||
						copyState.score >
							bestComplete.score {

						bestComplete = &copyState
					}
					continue
				}

				if slots > 1 {
					nextStates = append(nextStates, next)
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			return nextStates[i].rank > nextStates[j].rank
		})
		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	if bestComplete != nil && len(bestComplete.routes) > 0 {
		return bestComplete.routes, nil
	}

	r.reserved = savedReservations
	rt, _, err := r.findRoute(total)
	if err != nil {
		return nil, err
	}
	return []*route.Route{rt}, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++

	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++

	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}

			r.learnSuccess(key, amt+r.reserved[key])
			if r.suspect[key] > 0 {
				r.suspect[key]--
			}
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}

	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.suspect[key] += 2
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*2 + 8
	if r.attemptLimit < 12 {
		r.attemptLimit = 12
	}
	if r.attemptLimit > 36 {
		r.attemptLimit = 36
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)

	lowMode := math.Exp(-x / 0.05)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.032))
	p := 0.48*lowMode + 0.52*highMode

	if p < 0.004 {
		return 0.004
	}
	if p > 0.988 {
		return 0.988
	}
	return p
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case failure.count >= 3 && ratio > 0.25:
			return 0
		case failure.count >= 2 && ratio > 0.38:
			return 0
		case ratio > 0.68:
			return 0
		case ratio > 0.50:
			retryScale = 0.16
		case ratio > 0.34:
			retryScale = 0.34
		case ratio > 0.20:
			retryScale = 0.58
		default:
			retryScale = 0.78
		}

		if failure.count >= 2 {
			retryScale *= 0.55
		}
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		p = 0.996
	} else if belief.upperFail > 0 && total >= belief.upperFail {
		p = 0.006
	} else if belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		evidence := 0.992 - 0.982*pos
		p = 0.12*p + 0.88*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.30 {
			scale := 1 - 0.94*(ratio-0.30)/0.70
			if scale < 0.06 {
				scale = 0.06
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.65 * math.Exp(-distance/0.22)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.08 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))

		weight := 0.28
		if belief.successes+belief.failures >= 3 {
			weight = 0.40
		}
		p = (1-weight)*p + weight*q
	}

	p *= retryScale
	if p < 0.0015 {
		return 0.0015
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	reserved := r.reserved[edge.key]
	if reserved > edge.capacity || amt > edge.capacity-reserved {
		return 0
	}

	return r.liquidityProbability(edge, reserved+amt)
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 330_000.0
		hopPenalty = 900.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 18_000
			edgeScore += float64(r.suspect[edge.key]) * 210_000

			if r.reserved[edge.key] > 0 &&
				edge.key.from != r.source {

				edgeScore += 65_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateReserveInto(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amt
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveInto(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if maximum < minimum {
		return
	}
	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        int
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
}

func (r *candidateRouter) planScore(routes []*route.Route,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	total lnwire.MilliSatoshi, complete bool) float64 {

	score := 0.0
	for key, amount := range reservations {
		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		p := r.liquidityProbability(edge, amount)
		if p <= 0 {
			return math.Inf(-1)
		}
		score += math.Log(p)
	}

	var fees lnwire.MilliSatoshi
	uses := make(map[candidateEdgeKey]uint32)

	for _, rt := range routes {
		finalAmt := candidateFinalAmount(rt)
		if rt.TotalAmount > finalAmt {
			fees += rt.TotalAmount - finalAmt
		}

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if ok {
				uses[key]++
			}
		}
	}

	score -= float64(fees) / 5_000_000
	if len(routes) > 1 {
		score -= 0.105 * float64(len(routes)-1)
	}

	for key, count := range uses {
		if count > 1 && key.from != r.source {
			score -= 0.025 * float64(count-1)
		}
	}

	if !complete && total > 0 {
		sent := total
		for _, rt := range routes {
			sent -= candidateFinalAmount(rt)
		}
		progress := 1 - float64(sent)/float64(total)
		score += 0.45 * progress
	}

	return score
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots int) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	minimum := lnwire.MilliSatoshi(1)
	maximum := remaining - lnwire.MilliSatoshi(slots-1)
	if maximum < minimum {
		return nil
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(
		&sizes, seen, base/2, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, base*3/4, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, base, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, base*5/4, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, base*3/2, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, base*2, minimum, maximum,
	)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/4,
			minimum, maximum,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/3,
			minimum, maximum,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2,
			minimum, maximum,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8,
			minimum, maximum,
		)
	}

	return sizes
}

func (r *candidateRouter) planWithParts(total lnwire.MilliSatoshi,
	parts int) ([]*route.Route, float64, bool) {

	const beamWidth = 7

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	initialReservations := candidateCopyReservations(r.reserved)
	states := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: initialReservations,
	}}

	for depth := 0; depth < parts; depth++ {
		var expanded []candidatePlanState

		for _, state := range states {
			sizes := r.shardSizes(state.remaining, state.slots)
			for _, size := range sizes {
				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				rt, _, err := r.findRoute(size)
				if err != nil {
					continue
				}

				reservations := candidateCopyReservations(
					state.reservations,
				)
				candidateReserveInto(reservations, rt)

				routes := append(
					append([]*route.Route(nil), state.routes...),
					rt,
				)
				remaining := state.remaining - size
				slots := state.slots - 1
				complete := remaining == 0 && slots == 0

				if (remaining == 0) != (slots == 0) {
					continue
				}

				nextState := candidatePlanState{
					remaining:    remaining,
					slots:        slots,
					routes:       routes,
					reservations: reservations,
				}
				nextState.score = r.planScore(
					routes, reservations, total, complete,
				)
				if math.IsInf(nextState.score, -1) {
					continue
				}

				expanded = append(expanded, nextState)
			}
		}

		if len(expanded) == 0 {
			return nil, 0, false
		}

		sort.Slice(expanded, func(i, j int) bool {
			return expanded[i].score > expanded[j].score
		})
		if len(expanded) > beamWidth {
			expanded = expanded[:beamWidth]
		}
		states = expanded
	}

	for _, state := range states {
		if state.remaining == 0 && state.slots == 0 {
			return state.routes, state.score, true
		}
	}

	return nil, 0, false
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32, inFlight uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	full, fullLogProb, fullErr := r.findRoute(total)
	if parts == 1 {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	if fullErr == nil && fullLogProb >= math.Log(0.72) &&
		r.lastFailedShard == 0 {

		return []*route.Route{full}, nil
	}

	maxPlanParts := int(parts)
	if maxPlanParts > 12 {
		maxPlanParts = 12
	}

	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	if fullErr == nil {
		reservations := candidateCopyReservations(r.reserved)
		candidateReserveInto(reservations, full)
		bestPlan = []*route.Route{full}
		bestScore = r.planScore(
			bestPlan, reservations, total, true,
		)
	}

	for count := 2; count <= maxPlanParts; count++ {
		plan, score, ok := r.planWithParts(total, count)
		if !ok {
			continue
		}

		if bestPlan == nil || score > bestScore {
			bestPlan = plan
			bestScore = score
		}

		if count >= 4 && bestPlan != nil &&
			len(bestPlan) < count-1 {

			break
		}
	}

	if bestPlan == nil {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	_ = inFlight
	return bestPlan, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft, inFlightHtlcs)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amt
	if edge := r.edges[key]; edge != nil {
		highEstimate := edge.capacity * 7 / 8
		if highEstimate > estimate {
			estimate = highEstimate
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt / 3
	if edge := r.edges[key]; edge != nil {
		lowEstimate := edge.capacity / 18
		if estimate > lowEstimate {
			estimate = lowEstimate
		}
	}
	if estimate <= 0 {
		estimate = 1
	}
	if belief.estimate == 0 || belief.estimate >= amt ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil {
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3
		r.lastFailedShard = candidateFinalAmount(rt)

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32
	avoid         map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(candidateVertexHash(e.key.to) +
		0x9e3779b97f4a7c15)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(uint64(e.baseFeeMsat) +
		uint64(e.feeRatePPM)<<17)
	x ^= candidateMix64(uint64(e.timeLockDelta) +
		uint64(e.minHTLC)<<16)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		avoid:          make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*2 + 8
	if r.attemptLimit < 16 {
		r.attemptLimit = 16
	}
	if r.attemptLimit > 40 {
		r.attemptLimit = 40
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio > 0.80:
			retryScale = 0.08
		case ratio > 0.66:
			retryScale = 0.22
		case ratio > 0.50:
			retryScale = 0.55
		default:
			retryScale = 0.88
		}

		if failure.count > 1 {
			retryScale *= math.Pow(
				0.82, float64(failure.count-1),
			)
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.010 {
			p = 0.010
		}
		return p * retryScale
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		evidence := 0.99 - 0.98*pos
		p = 0.15*p + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.45 {
			scale := 1 - 0.94*(ratio-0.45)/0.55
			if scale < 0.06 {
				scale = 0.06
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.52 * math.Exp(-distance/0.16)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.10 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.72*p + 0.28*q
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateLabel struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64

	nextEdge  *candidateEdge
	nextLabel *candidateLabel
	active    bool
}

type candidateLabelQueue []*candidateLabel

func (q candidateLabelQueue) Len() int {
	return len(q)
}

func (q candidateLabelQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateLabelQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateLabelQueue) Push(x any) {
	*q = append(*q, x.(*candidateLabel))
}

func (q *candidateLabelQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func candidateAcceptLabel(labels map[route.Vertex][]*candidateLabel,
	label *candidateLabel) bool {

	current := labels[label.node]
	for _, old := range current {
		if !old.active {
			continue
		}
		if old.score <= label.score &&
			old.required <= label.required {

			return false
		}
	}

	for _, old := range current {
		if !old.active {
			continue
		}
		if label.score <= old.score &&
			label.required <= old.required {

			old.active = false
		}
	}

	active := 0
	for _, old := range current {
		if old.active {
			active++
		}
	}

	const maxLabels = 8
	if active >= maxLabels {
		var worst *candidateLabel
		worstRank := math.Inf(-1)

		for _, old := range current {
			if !old.active {
				continue
			}
			rank := old.score + float64(old.required)/1000
			if rank > worstRank {
				worst = old
				worstRank = rank
			}
		}

		newRank := label.score + float64(label.required)/1000
		if newRank >= worstRank {
			return false
		}
		worst.active = false
	}

	label.active = true
	labels[label.node] = append(current, label)
	return true
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 440_000.0
		hopPenalty = 180.0
	)

	start := &candidateLabel{
		node:     r.spec.Target,
		required: amt,
		active:   true,
	}
	labels := map[route.Vertex][]*candidateLabel{
		r.spec.Target: {start},
	}
	pq := &candidateLabelQueue{}
	heap.Push(pq, start)

	var sourceLabel *candidateLabel

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateLabel)
		if !item.active {
			continue
		}
		if item.node == r.source {
			sourceLabel = item
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 32_000
			edgeScore += float64(r.suspect[edge.key]) * 300_000
			edgeScore += float64(r.avoid[edge.key]) * 180_000

			if r.reserved[edge.key] > 0 {
				edgeScore += 360_000
			}

			label := &candidateLabel{
				node:      edge.key.from,
				score:     item.score + edgeScore,
				required:  sending,
				logProb:   item.logProb + math.Log(p),
				nextEdge:  edge,
				nextLabel: item,
			}
			if candidateAcceptLabel(labels, label) {
				heap.Push(pq, label)
			}
		}
	}

	if sourceLabel == nil {
		return nil, 0, errors.New("no route found")
	}

	var path []*candidateEdge
	for label := sourceLabel; label.node != r.spec.Target; {
		if label.nextEdge == nil || label.nextLabel == nil {
			return nil, 0, errors.New("broken route label")
		}
		path = append(path, label.nextEdge)
		label = label.nextLabel
	}

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLabel.logProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	node := r.source
	visited := make(map[route.Vertex]bool)
	for _, edge := range path {
		if visited[node] || edge.key.from != node {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true
		node = edge.key.to
	}
	if node != r.spec.Target {
		return nil, fmt.Errorf("route does not reach target")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateCopyCounts(
	src map[candidateEdgeKey]uint32,
) map[candidateEdgeKey]uint32 {

	dst := make(map[candidateEdgeKey]uint32, len(src))
	for key, count := range src {
		dst[key] = count
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

type candidateRouteChoice struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) routeChoices(
	amt lnwire.MilliSatoshi) []candidateRouteChoice {

	first, firstProb, err := r.findRoute(amt)
	if err != nil {
		return nil
	}

	choices := []candidateRouteChoice{{
		route:   first,
		logProb: firstProb,
	}}

	saved := candidateCopyCounts(r.avoid)
	for i := range first.Hops {
		key, ok := candidateRouteEdgeKey(first, i)
		if ok {
			r.avoid[key] += 2
		}
	}

	second, secondProb, err := r.findRoute(amt)
	r.avoid = saved
	if err == nil {
		choices = append(choices, candidateRouteChoice{
			route:   second,
			logProb: secondProb,
		})
	}

	return choices
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, remaining, remaining)
	candidateAddAmount(&sizes, seen, base, remaining)
	candidateAddAmount(&sizes, seen, base*3/2, remaining)
	candidateAddAmount(&sizes, seen, base*2, remaining)
	candidateAddAmount(&sizes, seen, remaining/2, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*2/3, remaining,
		)
	}

	return sizes
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	routes       []*route.Route
	score        float64
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(r.reserved),
	}}

	var best *candidatePlanState
	const beamWidth = 5

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		var next []candidatePlanState
		slots := parts - depth

		for _, state := range states {
			r.reserved = candidateCopyReservations(
				state.reservations,
			)

			for _, size := range r.shardSizes(
				state.remaining, slots,
			) {
				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				for _, choice := range r.routeChoices(size) {
					r.reserved = candidateCopyReservations(
						state.reservations,
					)
					r.reserveRoute(choice.route)

					fees := choice.route.TotalAmount - size
					score := state.score + choice.logProb -
						float64(fees)/4_000_000 -
						0.012*float64(len(choice.route.Hops))

					routes := append(
						[]*route.Route(nil), state.routes...,
					)
					routes = append(routes, choice.route)

					child := candidatePlanState{
						remaining: state.remaining - size,
						reservations: candidateCopyReservations(
							r.reserved,
						),
						routes: routes,
						score:  score,
					}

					if child.remaining == 0 {
						if best == nil ||
							child.score > best.score {

							copy := child
							best = &copy
						}
						continue
					}
					next = append(next, child)
				}
			}
		}

		sort.Slice(next, func(i, j int) bool {
			return next[i].score > next[j].score
		})
		if len(next) > beamWidth {
			next = next[:beamWidth]
		}
		states = next
	}

	if best == nil {
		return nil, errors.New("no route found")
	}
	return best.routes, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	if belief.estimate == 0 {
		belief.estimate = amt
	} else if amt > belief.estimate {
		belief.estimate = (belief.estimate + 2*amt) / 3
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 9 / 16
	if belief.lowerOK > 0 && estimate < belief.lowerOK {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	} else {
		belief.estimate = (2*belief.estimate + estimate) / 3
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*2 + 6
	if r.attemptLimit < 10 {
		r.attemptLimit = 10
	}
	if r.attemptLimit > 48 {
		r.attemptLimit = 48
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.052)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.034))
	p := 0.47*lowMode + 0.53*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.9995
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case failure.count >= 3 && ratio > 0.32:
			return 0
		case failure.count >= 2 && ratio > 0.48:
			return 0
		case ratio > 0.72:
			return 0
		case ratio > 0.58:
			retryScale = 0.20
		case ratio > 0.44:
			retryScale = 0.42
		case ratio > 0.28:
			retryScale = 0.66
		default:
			retryScale = 0.84
		}

		if failure.count >= 2 {
			retryScale *= 0.72
		}
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	switch {
	case belief.lowerOK > 0 && total <= belief.lowerOK:
		p = 0.996

	case belief.upperFail > 0 && total >= belief.upperFail:
		p = 0.004

	case belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK:

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.994 - 0.988*pos
		p = 0.15*p + 0.85*evidence

	case belief.upperFail > 0:
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.25 {
			scale := 1 - 0.90*(ratio-0.25)/0.75
			if scale < 0.10 {
				scale = 0.10
			}
			p *= scale
		}

	case belief.lowerOK > 0 && total > belief.lowerOK:
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.58 * math.Exp(-distance/0.20)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.075 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))

		weight := 0.16
		evidenceCount := belief.successes + belief.failures
		if evidenceCount >= 2 {
			weight = 0.24
		}
		if evidenceCount >= 4 {
			weight = 0.32
		}
		p = (1-weight)*p + weight*q
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	reserved := r.reserved[edge.key]
	if reserved > edge.capacity || amt > edge.capacity-reserved {
		return 0
	}

	return r.liquidityProbability(edge, reserved+amt)
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 540_000.0
		hopPenalty = 13_000.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += float64(r.suspect[edge.key]) * 270_000

			reserved := r.reserved[edge.key]
			if reserved > 0 && edge.key.from != r.source {
				load := float64(reserved) /
					float64(edge.capacity)
				if load > 0.95 {
					load = 0.95
				}
				edgeScore += 90_000 +
					260_000*load/(1.05-load)
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateReserveInto(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amt
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveInto(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if maximum < minimum {
		return
	}
	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        int
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
}

func (r *candidateRouter) planScore(routes []*route.Route,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	total lnwire.MilliSatoshi, complete bool) float64 {

	score := 0.0
	for key, amount := range reservations {
		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		p := r.liquidityProbability(edge, amount)
		if p <= 0 {
			return math.Inf(-1)
		}
		score += math.Log(p)
	}

	var fees lnwire.MilliSatoshi
	uses := make(map[candidateEdgeKey]uint32)

	for _, rt := range routes {
		finalAmt := candidateFinalAmount(rt)
		if rt.TotalAmount > finalAmt {
			fees += rt.TotalAmount - finalAmt
		}

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if ok {
				uses[key]++
			}
		}
	}

	score -= float64(fees) / 30_000_000
	if len(routes) > 1 {
		score -= 0.035 * float64(len(routes)-1)
	}

	for key, count := range uses {
		if count > 1 && key.from != r.source {
			score -= 0.012 * float64(count-1)
		}
	}

	if !complete && total > 0 {
		unsent := total
		for _, rt := range routes {
			unsent -= candidateFinalAmount(rt)
		}
		progress := 1 - float64(unsent)/float64(total)
		score += 0.30 * progress
	}

	return score
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots int) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	minimum := lnwire.MilliSatoshi(1)
	maximum := remaining - lnwire.MilliSatoshi(slots-1)
	if maximum < minimum {
		return nil
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(
		&sizes, seen, base*2/3, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, base*4/5, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, base, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, base*6/5, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, base*3/2, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, base*2, minimum, maximum,
	)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/4,
			minimum, maximum,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/3,
			minimum, maximum,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*2/5,
			minimum, maximum,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2,
			minimum, maximum,
		)
	}

	return sizes
}

func (r *candidateRouter) planWithParts(total lnwire.MilliSatoshi,
	parts int) ([]*route.Route, float64, bool) {

	const beamWidth = 6

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(r.reserved),
	}}

	for depth := 0; depth < parts; depth++ {
		var expanded []candidatePlanState

		for _, state := range states {
			sizes := r.shardSizes(state.remaining, state.slots)
			for _, size := range sizes {
				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				rt, _, err := r.findRoute(size)
				if err != nil {
					continue
				}

				reservations := candidateCopyReservations(
					state.reservations,
				)
				candidateReserveInto(reservations, rt)

				routes := append(
					append([]*route.Route(nil), state.routes...),
					rt,
				)
				remaining := state.remaining - size
				slots := state.slots - 1
				complete := remaining == 0 && slots == 0

				if (remaining == 0) != (slots == 0) {
					continue
				}

				nextState := candidatePlanState{
					remaining:    remaining,
					slots:        slots,
					routes:       routes,
					reservations: reservations,
				}
				nextState.score = r.planScore(
					routes, reservations, total, complete,
				)
				if math.IsInf(nextState.score, -1) {
					continue
				}

				expanded = append(expanded, nextState)
			}
		}

		if len(expanded) == 0 {
			return nil, 0, false
		}

		sort.Slice(expanded, func(i, j int) bool {
			if expanded[i].score == expanded[j].score {
				return len(expanded[i].routes) <
					len(expanded[j].routes)
			}
			return expanded[i].score > expanded[j].score
		})
		if len(expanded) > beamWidth {
			expanded = expanded[:beamWidth]
		}
		states = expanded
	}

	for _, state := range states {
		if state.remaining == 0 && state.slots == 0 {
			return state.routes, state.score, true
		}
	}

	return nil, 0, false
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	full, fullLogProb, fullErr := r.findRoute(total)
	if parts == 1 {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	if fullErr == nil && fullLogProb >= math.Log(0.94) &&
		r.lastFailedShard == 0 {

		return []*route.Route{full}, nil
	}

	maxPlanParts := int(parts)

	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	if fullErr == nil {
		reservations := candidateCopyReservations(r.reserved)
		candidateReserveInto(reservations, full)
		bestPlan = []*route.Route{full}
		bestScore = r.planScore(
			bestPlan, reservations, total, true,
		)
	}

	for count := 2; count <= maxPlanParts; count++ {
		plan, score, ok := r.planWithParts(total, count)
		if !ok {
			continue
		}
		if bestPlan == nil || score > bestScore {
			bestPlan = plan
			bestScore = score
		}
	}

	if bestPlan == nil {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	return bestPlan, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amt
	if edge := r.edges[key]; edge != nil && edge.capacity > 0 {
		ratio := float64(amt) / float64(edge.capacity)
		switch {
		case ratio >= 0.08:
			estimate = edge.capacity * 7 / 8
		case ratio >= 0.035:
			estimate = edge.capacity * 3 / 4
		default:
			probeEstimate := amt * 2
			if probeEstimate > estimate {
				estimate = probeEstimate
			}
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt / 3
	if edge := r.edges[key]; edge != nil {
		lowEstimate := edge.capacity / 18
		if estimate > lowEstimate {
			estimate = lowEstimate
		}
	}
	if estimate <= 0 {
		estimate = 1
	}
	if belief.estimate == 0 || belief.estimate >= amt ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil {
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
			if r.suspect[key] > 0 {
				r.suspect[key]--
			}
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 4
		r.lastFailedShard = candidateFinalAmount(rt)

	default:
		r.suspect[key] += 3
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*4 + 12
	if r.attemptLimit < 24 {
		r.attemptLimit = 24
	}
	if r.attemptLimit > 80 {
		r.attemptLimit = 80
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) || r.policyBlocked[edge.key] {
		return 0
	}

	reserved := r.reserved[edge.key]
	total := amt + reserved
	if total < amt || total > edge.capacity {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio > 0.80:
			retryScale = 0.10
		case ratio > 0.62:
			retryScale = 0.32
		case ratio > 0.45:
			retryScale = 0.58
		default:
			retryScale = 0.78
		}
		if failure.count > 2 {
			retryScale *= 0.8
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	prior := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return prior * retryScale
	}

	p := prior
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		p = 0.995
	} else if belief.upperFail > 0 && total >= belief.upperFail {
		p = 0.006
	} else if belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.992 - 0.984*pos
		p = 0.15*prior + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.40 {
			scale := 1 - 0.94*(ratio-0.40)/0.60
			if scale < 0.06 {
				scale = 0.06
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.52 * math.Exp(-distance/0.16)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.10 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		weight := 0.22
		if belief.successes+belief.failures >= 3 {
			weight = 0.32
		}
		p = (1-weight)*p + weight*q
	}

	p *= retryScale
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64

	via   *candidateEdge
	down  *candidateDijkstraItem
	active bool
	idx    int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	if q[i].score == q[j].score {
		return q[i].required < q[j].required
	}
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	item.idx = -1
	*q = old[:n-1]
	return item
}

func candidateAddLabel(
	labels map[route.Vertex][]*candidateDijkstraItem,
	item *candidateDijkstraItem) bool {

	const maxLabels = 8

	current := labels[item.node]
	for _, old := range current {
		if old.active && old.score <= item.score &&
			old.required <= item.required {

			return false
		}
	}

	kept := current[:0]
	for _, old := range current {
		if old.active && item.score <= old.score &&
			item.required <= old.required {

			old.active = false
			continue
		}
		if old.active {
			kept = append(kept, old)
		}
	}

	item.active = true
	kept = append(kept, item)

	if len(kept) > maxLabels {
		minRequired := kept[0]
		for _, candidate := range kept[1:] {
			if candidate.required < minRequired.required {
				minRequired = candidate
			}
		}

		var worst *candidateDijkstraItem
		for _, candidate := range kept {
			if candidate == minRequired && len(kept) > 1 {
				continue
			}
			if worst == nil || candidate.score > worst.score {
				worst = candidate
			}
		}
		if worst == nil {
			worst = kept[len(kept)-1]
		}
		worst.active = false

		filtered := kept[:0]
		for _, candidate := range kept {
			if candidate.active {
				filtered = append(filtered, candidate)
			}
		}
		kept = filtered
	}

	labels[item.node] = kept
	return item.active
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 420_000.0
		hopPenalty = 220.0
	)

	target := &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
		active:   true,
	}

	labels := make(map[route.Vertex][]*candidateDijkstraItem)
	labels[r.spec.Target] = []*candidateDijkstraItem{target}

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, target)

	var sourceItem *candidateDijkstraItem

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		if !item.active {
			continue
		}
		if item.node == r.source {
			sourceItem = item
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee
			if sending < amtOver {
				continue
			}

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += float64(r.edgeUses[edge.key]) * 20_000
			edgeScore += float64(r.suspect[edge.key]) * 220_000

			if reserved := r.reserved[edge.key]; reserved > 0 {
				reusePenalty := 280_000.0
				total := reserved + amtOver
				if edge.key.from == r.source {
					reusePenalty = 25_000
				} else if belief, ok := r.beliefs[edge.key]; ok &&
					belief.lowerOK >= total {

					reusePenalty = 45_000
				}
				edgeScore += reusePenalty
			}

			next := &candidateDijkstraItem{
				node:     edge.key.from,
				score:    item.score + edgeScore,
				required: sending,
				logProb:  item.logProb + math.Log(p),
				via:      edge,
				down:     item,
			}
			if candidateAddLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if sourceItem == nil {
		return nil, 0, errors.New("no route found")
	}

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)
	for item := sourceItem; item.node != r.spec.Target; {
		if item.via == nil || item.down == nil {
			return nil, 0, errors.New("broken route label")
		}
		if visited[item.node] {
			return nil, 0, errors.New("route contains cycle")
		}
		visited[item.node] = true
		path = append(path, item.via)
		item = item.down
	}

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceItem.logProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	node := r.source
	for _, edge := range path {
		if edge.key.from != node {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		node = edge.key.to
	}
	if node != r.spec.Target {
		return nil, errors.New("route does not reach target")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 || max <= 0 {
		return
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) planningSizes(
	remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, base/2, remaining)
	candidateAddAmount(&sizes, seen, base*3/4, remaining)
	candidateAddAmount(&sizes, seen, base, remaining)
	candidateAddAmount(&sizes, seen, base*5/4, remaining)
	candidateAddAmount(&sizes, seen, base*3/2, remaining)
	candidateAddAmount(&sizes, seen, base*2, remaining)
	candidateAddAmount(&sizes, seen, remaining, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/3, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*3/4, remaining,
		)
	}

	var evidence []lnwire.MilliSatoshi
	evidenceSeen := make(map[lnwire.MilliSatoshi]bool)
	addEvidence := func(value lnwire.MilliSatoshi) {
		if value < base/3 || value > remaining {
			return
		}
		if !evidenceSeen[value] {
			evidenceSeen[value] = true
			evidence = append(evidence, value)
		}
	}

	for key, belief := range r.beliefs {
		reserved := r.reserved[key]
		if belief.lowerOK > reserved {
			available := belief.lowerOK - reserved
			addEvidence(available * 9 / 10)
			addEvidence(available)
		}
		if belief.upperFail > reserved {
			available := belief.upperFail - reserved
			addEvidence(available / 2)
			addEvidence(available * 5 / 8)
		}
		if belief.estimate > reserved {
			available := belief.estimate - reserved
			addEvidence(available * 4 / 5)
		}
	}

	for key, failure := range r.currentFails {
		reserved := r.reserved[key]
		if failure.upper > reserved {
			available := failure.upper - reserved
			addEvidence(available / 2)
			addEvidence(available * 5 / 8)
		}
	}

	for _, edges := range r.incomingEdges {
		for _, edge := range edges {
			reserved := r.reserved[edge.key]
			if edge.key.from == r.source {
				balance, ok := r.localBalances[edge.key.chanID]
				if ok && balance > reserved {
					addEvidence((balance - reserved) * 19 / 20)
				}
				continue
			}

			limit := edge.capacity
			if edge.maxHTLC > 0 && edge.maxHTLC < limit {
				limit = edge.maxHTLC
			}
			if limit > reserved {
				addEvidence((limit - reserved) * 17 / 20)
			}
		}
	}

	sort.Slice(evidence, func(i, j int) bool {
		di := math.Abs(math.Log(
			float64(evidence[i]) / float64(base),
		))
		dj := math.Abs(math.Log(
			float64(evidence[j]) / float64(base),
		))
		if di == dj {
			return evidence[i] > evidence[j]
		}
		return di < dj
	})

	if len(evidence) > 6 {
		evidence = evidence[:6]
	}
	for _, value := range evidence {
		candidateAddAmount(&sizes, seen, value, remaining)
	}

	sort.Slice(sizes, func(i, j int) bool {
		return sizes[i] > sizes[j]
	})
	return sizes
}

func (r *candidateRouter) planOnce(total lnwire.MilliSatoshi,
	parts uint32, sizeBias float64) ([]*route.Route, float64, bool) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	remaining := total
	slots := parts
	var plan []*route.Route
	jointScore := 0.0

	for remaining > 0 && slots > 0 {
		sizes := r.planningSizes(remaining, slots)
		base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		var bestRoute *route.Route
		bestSize := lnwire.MilliSatoshi(0)
		bestLogProb := 0.0
		bestUtility := math.Inf(-1)

		for _, size := range sizes {
			rt, logProb, err := r.findRoute(size)
			if err != nil {
				continue
			}

			fees := rt.TotalAmount - size
			sizeReward := math.Log(
				float64(size) / float64(base),
			)
			utility := logProb + sizeBias*sizeReward -
				float64(fees)/4_000_000

			if bestRoute == nil || utility > bestUtility {
				bestRoute = rt
				bestSize = size
				bestLogProb = logProb
				bestUtility = utility
			}
		}

		if bestRoute == nil {
			return nil, 0, false
		}

		fees := bestRoute.TotalAmount - bestSize
		jointScore += bestLogProb -
			float64(fees)/4_000_000 - 0.04

		plan = append(plan, bestRoute)
		r.reserveRoute(bestRoute)
		remaining -= bestSize
		slots--
	}

	if remaining != 0 || len(plan) == 0 {
		return nil, 0, false
	}
	return plan, jointScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	if rt, logProb, err := r.findRoute(total); err == nil {
		fees := rt.TotalAmount - total
		bestPlan = []*route.Route{rt}
		bestScore = logProb - float64(fees)/4_000_000 - 0.04
	}

	if parts > 1 {
		for _, bias := range []float64{0.8, 1.8, 3.5} {
			plan, score, ok := r.planOnce(total, parts, bias)
			if !ok {
				continue
			}
			if bestPlan == nil || score > bestScore {
				bestPlan = plan
				bestScore = score
			}
		}
	}

	if bestPlan == nil && parts > 1 {
		base := (total + lnwire.MilliSatoshi(parts) - 1) /
			lnwire.MilliSatoshi(parts)
		bestUtility := math.Inf(-1)

		for _, size := range r.planningSizes(total, parts) {
			rt, logProb, err := r.findRoute(size)
			if err != nil {
				continue
			}
			fees := rt.TotalAmount - size
			utility := logProb +
				1.4*math.Log(float64(size)/float64(base)) -
				float64(fees)/4_000_000
			if bestPlan == nil || utility > bestUtility {
				bestPlan = []*route.Route{rt}
				bestUtility = utility
			}
		}
	}

	if bestPlan == nil {
		return nil, errors.New("no route found")
	}

	sort.SliceStable(bestPlan, func(i, j int) bool {
		return candidateFinalAmount(bestPlan[i]) >
			candidateFinalAmount(bestPlan[j])
	})
	return bestPlan, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	if rt == nil {
		return
	}
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil {
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = 18 + int(maxParts)*4
	if r.attemptLimit < 24 {
		r.attemptLimit = 24
	}
	if r.attemptLimit > 60 {
		r.attemptLimit = 60
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if amt <= 0 || capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.045)
	highMode := 1 / (1 + math.Exp((x-0.92)/0.035))
	p := 0.47*lowMode + 0.53*highMode

	if p < 0.004 {
		return 0.004
	}
	if p > 0.988 {
		return 0.988
	}
	return p
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity || r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio > 0.78:
			retryScale = 0.025
		case ratio > 0.62:
			retryScale = 0.10
		case ratio > 0.48:
			retryScale = 0.24
		case ratio > 0.34:
			retryScale = 0.43
		case ratio > 0.22:
			retryScale = 0.67
		default:
			retryScale = 0.84
		}
		if failure.count >= 2 {
			retryScale *= 0.68
		}
		if failure.count >= 4 {
			retryScale *= 0.55
		}
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	switch {
	case belief.lowerOK > 0 && total <= belief.lowerOK:
		p = 0.996

	case belief.upperFail > 0 && total >= belief.upperFail:
		p = 0.005

	case belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK:

		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(total-belief.lowerOK) / width
		if position < 0 {
			position = 0
		}
		if position > 1 {
			position = 1
		}
		evidence := 0.994 - 0.988*position
		p = 0.10*p + 0.90*evidence

	case belief.upperFail > 0:
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.22 {
			scale := 1 - 0.94*(ratio-0.22)/0.78
			if scale < 0.05 {
				scale = 0.05
			}
			p *= scale
		}

	case belief.lowerOK > 0 && total > belief.lowerOK:
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.68 * math.Exp(-distance/0.20)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.075 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		estimateProbability := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))

		weight := 0.24
		if belief.successes+belief.failures >= 3 {
			weight = 0.36
		}
		p = (1-weight)*p + weight*estimateProbability
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	reserved := r.reserved[edge.key]
	if reserved > edge.capacity || amt > edge.capacity-reserved {
		return 0
	}

	return r.liquidityProbability(edge, reserved+amt)
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	index    int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateDijkstraQueue) Push(value any) {
	item := value.(*candidateDijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 260_000.0
		hopPenalty = 700.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	bestScore[r.spec.Target] = 0

	queue := &candidateDijkstraQueue{}
	heap.Push(queue, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProbability float64

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProbability = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amountOverEdge := item.required
			probability := r.probability(edge, amountOverEdge)
			if probability <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOverEdge)
			}
			sending := amountOverEdge + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(probability)) +
				hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 11_000
			edgeScore += float64(r.suspect[edge.key]) * 42_000
			edgeScore += extraPenalty[edge.key]

			if r.reserved[edge.key] > 0 &&
				edge.key.from != r.source {

				edgeScore += 22_000
			}

			score := item.score + edgeScore
			oldScore, found := bestScore[edge.key.from]
			if found && score >= oldScore {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(queue, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(probability),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProbability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] + outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route,
	channelIndex int) (lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}

	hop := rt.Hops[channelIndex]
	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteHash(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	hash := candidateMix64(candidateVertexHash(rt.SourcePubKey))
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		hash ^= candidateMix64(
			key.chanID + uint64(i+1)*0x9e3779b97f4a7c15,
		)
		hash ^= candidateMix64(candidateVertexHash(key.to))
	}
	return candidateMix64(hash)
}

func candidateCopyReservations(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	copy := make(
		map[candidateEdgeKey]lnwire.MilliSatoshi, len(source),
	)
	for key, amount := range source {
		copy[key] = amount
	}
	return copy
}

func candidateReserveInto(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amount
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveInto(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}

	for _, rt := range r.held[len(r.held)-count:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if maximum < minimum {
		return
	}
	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots int) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	minimum := lnwire.MilliSatoshi(1)
	maximum := remaining - lnwire.MilliSatoshi(slots-1)
	if maximum < minimum {
		return nil
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&values, seen, base, minimum, maximum)
	candidateAddAmount(&values, seen, base*3/4, minimum, maximum)
	candidateAddAmount(&values, seen, base*5/4, minimum, maximum)
	candidateAddAmount(&values, seen, base/2, minimum, maximum)
	candidateAddAmount(&values, seen, base*3/2, minimum, maximum)
	candidateAddAmount(&values, seen, base*2, minimum, maximum)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&values, seen, r.lastFailedShard/4, minimum, maximum,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard/3, minimum, maximum,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard/2, minimum, maximum,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard*5/8,
			minimum, maximum,
		)
	}

	for _, edge := range r.edges {
		if edge.key.to != r.spec.Target &&
			edge.key.from != r.source {

			continue
		}

		candidateAddAmount(
			&values, seen, edge.capacity*9/20, minimum, maximum,
		)
		candidateAddAmount(
			&values, seen, edge.capacity*4/5, minimum, maximum,
		)

		if belief, ok := r.beliefs[edge.key]; ok {
			if belief.lowerOK > 0 {
				candidateAddAmount(
					&values, seen, belief.lowerOK,
					minimum, maximum,
				)
			}
			if belief.upperFail > 0 {
				candidateAddAmount(
					&values, seen, belief.upperFail*3/5,
					minimum, maximum,
				)
			}
		}
	}

	sort.SliceStable(values, func(i, j int) bool {
		di := math.Abs(float64(values[i] - base))
		dj := math.Abs(float64(values[j] - base))
		return di < dj
	})

	const maximumCandidates = 14
	if len(values) > maximumCandidates {
		values = values[:maximumCandidates]
	}

	return values
}

type candidateRouteOption struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) routeOptions(
	amt lnwire.MilliSatoshi) []candidateRouteOption {

	const optionCount = 3

	penalties := make(map[candidateEdgeKey]float64)
	seen := make(map[uint64]bool)
	var options []candidateRouteOption

	for option := 0; option < optionCount; option++ {
		rt, logProbability, err := r.findRoute(amt, penalties)
		if err != nil {
			break
		}

		hash := candidateRouteHash(rt)
		if !seen[hash] {
			seen[hash] = true
			options = append(options, candidateRouteOption{
				route:   rt,
				logProb: logProbability,
			})
		}

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}

			penalty := 420_000.0
			if key.from == r.source {
				penalty = 150_000
			}
			penalties[key] += penalty
		}
	}

	return options
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        int
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
}

func (r *candidateRouter) planScore(routes []*route.Route,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	total lnwire.MilliSatoshi, complete bool) float64 {

	score := 0.0
	for key, amount := range reservations {
		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		probability := r.liquidityProbability(edge, amount)
		if probability <= 0 {
			return math.Inf(-1)
		}
		score += math.Log(probability)
	}

	var fees lnwire.MilliSatoshi
	uses := make(map[candidateEdgeKey]uint32)

	for _, rt := range routes {
		finalAmount := candidateFinalAmount(rt)
		if rt.TotalAmount > finalAmount {
			fees += rt.TotalAmount - finalAmount
		}

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if ok {
				uses[key]++
			}
		}
	}

	score -= float64(fees) / 6_000_000
	if len(routes) > 1 {
		score -= 0.045 * float64(len(routes)-1)
	}

	for key, count := range uses {
		if count > 1 && key.from != r.source {
			score -= 0.045 * float64(count-1)
		}
	}

	if !complete && total > 0 {
		sent := total
		for _, rt := range routes {
			sent -= candidateFinalAmount(rt)
		}
		progress := 1 - float64(sent)/float64(total)
		score += 0.35 * progress
	}

	return score
}

func (r *candidateRouter) planWithParts(total lnwire.MilliSatoshi,
	parts int) ([]*route.Route, float64, bool) {

	const beamWidth = 10

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(r.reserved),
	}}

	for depth := 0; depth < parts; depth++ {
		var expanded []candidatePlanState

		for _, state := range states {
			sizes := r.shardSizes(state.remaining, state.slots)
			for _, size := range sizes {
				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				options := r.routeOptions(size)
				for _, option := range options {
					reservations := candidateCopyReservations(
						state.reservations,
					)
					candidateReserveInto(
						reservations, option.route,
					)

					routes := append(
						append(
							[]*route.Route(nil),
							state.routes...,
						),
						option.route,
					)
					remaining := state.remaining - size
					slots := state.slots - 1

					if remaining < 0 {
						continue
					}
					if (remaining == 0) != (slots == 0) {
						continue
					}

					nextState := candidatePlanState{
						remaining:    remaining,
						slots:        slots,
						routes:       routes,
						reservations: reservations,
					}
					nextState.score = r.planScore(
						routes, reservations, total,
						remaining == 0,
					)
					if math.IsInf(nextState.score, -1) {
						continue
					}

					expanded = append(expanded, nextState)
				}
			}
		}

		if len(expanded) == 0 {
			return nil, 0, false
		}

		sort.SliceStable(expanded, func(i, j int) bool {
			return expanded[i].score > expanded[j].score
		})
		if len(expanded) > beamWidth {
			expanded = expanded[:beamWidth]
		}
		states = expanded
	}

	for _, state := range states {
		if state.remaining == 0 && state.slots == 0 {
			return state.routes, state.score, true
		}
	}

	return nil, 0, false
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	full, fullLogProbability, fullErr := r.findRoute(total, nil)
	if parts == 1 {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	if fullErr == nil &&
		fullLogProbability >= math.Log(0.82) &&
		r.lastFailedShard == 0 {

		return []*route.Route{full}, nil
	}

	maxPlanParts := int(parts)
	if maxPlanParts > 16 {
		maxPlanParts = 16
	}
	if lnwire.MilliSatoshi(maxPlanParts) > total {
		maxPlanParts = int(total)
	}
	if maxPlanParts < 1 {
		return nil, errors.New("payment amount too small")
	}

	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	if fullErr == nil {
		reservations := candidateCopyReservations(r.reserved)
		candidateReserveInto(reservations, full)
		bestPlan = []*route.Route{full}
		bestScore = r.planScore(
			bestPlan, reservations, total, true,
		)
	}

	for count := 2; count <= maxPlanParts; count++ {
		plan, score, ok := r.planWithParts(total, count)
		if !ok {
			continue
		}
		if bestPlan == nil || score > bestScore {
			bestPlan = plan
			bestScore = score
		}
	}

	if bestPlan == nil {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	return bestPlan, nil
}

func (r *candidateRouter) routeFits(rt *route.Route) bool {
	added := make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return false
		}
		edge := r.edges[key]
		if edge == nil || r.policyBlocked[key] {
			return false
		}

		amount, ok := candidateRouteAmount(rt, i)
		if !ok || !edge.policyAllows(amount) {
			return false
		}

		added[key] += amount
		total := r.reserved[key] + added[key]
		if total > edge.capacity {
			return false
		}
		if key.from == r.source {
			balance, ok := r.localBalances[key.chanID]
			if !ok || total > balance {
				return false
			}
		}
		if failure, ok := r.currentFails[key]; ok &&
			failure.upper > 0 && total >= failure.upper {

			return false
		}
	}

	return true
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmount := candidateFinalAmount(rt)
		if finalAmount > 0 && finalAmount <= amt && r.routeFits(rt) {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amount lnwire.MilliSatoshi) {

	if amount <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amount >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amount > belief.lowerOK {
		belief.lowerOK = amount
	}
	if belief.upperFail > 0 && amount >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amount
	if edge := r.edges[key]; edge != nil {
		highEstimate := edge.capacity * 17 / 20
		if highEstimate > estimate {
			estimate = highEstimate
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amount lnwire.MilliSatoshi) {

	if amount <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amount < current.upper {
		current.upper = amount
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amount < belief.upperFail {
		belief.upperFail = amount
	}
	if belief.lowerOK >= amount {
		belief.lowerOK = 0
	}

	estimate := amount / 4
	if edge := r.edges[key]; edge != nil {
		lowEstimate := edge.capacity / 20
		if estimate > lowEstimate {
			estimate = lowEstimate
		}
	}
	if estimate <= 0 {
		estimate = 1
	}
	if belief.estimate == 0 || belief.estimate >= amount ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amount, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amount+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failureIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failureIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failureIndex = i + 1
				break
			}
		}
	}

	if failureIndex < 0 {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	passedEdges := failureIndex
	if passedEdges > len(rt.Hops) {
		passedEdges = len(rt.Hops)
	}

	for i := 0; i < passedEdges; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amount+r.reserved[key])
		}
	}

	if failureIndex >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amountOverEdge, ok := candidateRouteAmount(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	totalRequired := amountOverEdge + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}
